// УЧЕБНЫЙ ДЕНЬ И ПЕРЕХОДНЫЙ ЧАС. Тесты написаны ДО кода (P8).
//
// ⚠️ ЗАЧЕМ ОТДЕЛЬНОЕ ПОНЯТИЕ. Календарная дата и учебный день — РАЗНЫЕ величины.
// Пользователь сам назначает час, в который у него сменяется учебный день; всё,
// что получено до этого часа, принадлежит предыдущему учебному дню. Сервер об
// этом не знает и знать не должен: он отвечает на ту дату, которую НАЗВАЛИ.
//
// ⚠️ ПРАВИЛО ПОДПИСИ, СОГЛАСОВАНО С ВЛАДЕЛЬЦЕМ. Разбиение времени на блоки
// однозначно (границы — переходный час каждых суток), а вот КАКОЙ ДАТОЙ подписать
// блок — соглашение, и оба варианта выглядят естественно:
//   переход 04:00 → блок [1-го 04:00 … 2-го 04:00) зовётся ПЕРВЫМ  (дата начала);
//   переход 18:00 → блок [1-го 18:00 … 2-го 18:00) зовётся ВТОРЫМ  (дата конца).
// Общее правило, покрывающее оба: блок подписывается датой ТОГО УТРА, которое в
// него попадает. Технически: переход до полудня → дата начала, иначе → дата конца.
// ⚠️ Ошибиться здесь = сдвинуть ВЕСЬ календарь на сутки, причём молча.
import { describe, expect, it } from 'vitest';
import {
  learningDayOf, nextLearningDay, normalizeTransition,
  hhmmOfMinutes, minutesOfHHMM, MINUTES_IN_DAY,
} from '../learning-day';

// Локальное время — намеренно: учебный день у человека местный, не UTC.
const момент = (iso: string): Date => new Date(iso);
const чч = (h: number, m = 0): number => h * 60 + m;

describe('learningDayOf — переход ДО полудня (подпись датой начала блока)', () => {
  const переход = чч(4); // 04:00 — пример владельца

  it('до переходного часа ролик принадлежит ПРЕДЫДУЩЕМУ учебному дню', () => {
    // 2 января 03:00 — человек ещё «не ложился»: это всё ещё 1 января.
    expect(learningDayOf(момент('2026-01-02T03:00:00'), переход)).toBe('2026-01-01');
  });

  it('ровно в переходный час день уже НОВЫЙ (граница принадлежит новому дню)', () => {
    expect(learningDayOf(момент('2026-01-02T04:00:00'), переход)).toBe('2026-01-02');
  });

  it('на минуту раньше — ещё старый день', () => {
    expect(learningDayOf(момент('2026-01-02T03:59:00'), переход)).toBe('2026-01-01');
  });

  it('днём и вечером — календарная дата совпадает с учебной', () => {
    expect(learningDayOf(момент('2026-01-02T12:00:00'), переход)).toBe('2026-01-02');
    expect(learningDayOf(момент('2026-01-02T23:59:00'), переход)).toBe('2026-01-02');
  });
});

describe('learningDayOf — переход ПОСЛЕ полудня (подпись датой конца блока)', () => {
  const переход = чч(18); // 18:00 — разобранный владельцем сценарий

  it('до переходного часа 1 января — это учебное 1 января', () => {
    expect(learningDayOf(момент('2026-01-01T17:00:00'), переход)).toBe('2026-01-01');
    expect(learningDayOf(момент('2026-01-01T17:30:00'), переход)).toBe('2026-01-01');
  });

  it('⚠️ ПОСЛЕ переходного часа 1 января — это уже учебное 2 января', () => {
    // Ровно тот случай: в 18:01 кнопка зовётся «следующий учебный день»,
    // и собранный по ней день должен лечь во 2 января, а не в 1-е.
    expect(learningDayOf(момент('2026-01-01T18:01:00'), переход)).toBe('2026-01-02');
  });

  it('ночь и утро 2 января — всё ещё учебное 2 января', () => {
    expect(learningDayOf(момент('2026-01-02T02:00:00'), переход)).toBe('2026-01-02');
    expect(learningDayOf(момент('2026-01-02T10:00:00'), переход)).toBe('2026-01-02');
  });

  it('следующий переход переводит на 3 января', () => {
    expect(learningDayOf(момент('2026-01-02T18:00:00'), переход)).toBe('2026-01-03');
  });
});

describe('learningDayOf — краевые значения переходного часа', () => {
  it('полночь: учебный день совпадает с календарным', () => {
    expect(learningDayOf(момент('2026-01-02T00:00:00'), 0)).toBe('2026-01-02');
    expect(learningDayOf(момент('2026-01-02T23:59:00'), 0)).toBe('2026-01-02');
  });

  it('ровно полдень считается «после полудня» — подпись датой конца блока', () => {
    // Граница соглашения названа явно, чтобы её нельзя было сдвинуть молча.
    expect(learningDayOf(момент('2026-01-01T11:59:00'), чч(12))).toBe('2026-01-01');
    expect(learningDayOf(момент('2026-01-01T12:00:00'), чч(12))).toBe('2026-01-02');
  });

  it('переход с минутами (18:30) работает так же, как ровный час', () => {
    expect(learningDayOf(момент('2026-01-01T18:29:00'), чч(18, 30))).toBe('2026-01-01');
    expect(learningDayOf(момент('2026-01-01T18:30:00'), чч(18, 30))).toBe('2026-01-02');
  });
});

describe('learningDayOf — переходы через границы календаря', () => {
  it('через конец месяца', () => {
    expect(learningDayOf(момент('2026-02-01T03:00:00'), чч(4))).toBe('2026-01-31');
  });

  it('через конец года', () => {
    expect(learningDayOf(момент('2026-01-01T02:00:00'), чч(4))).toBe('2025-12-31');
  });

  it('29 февраля високосного года не теряется', () => {
    expect(learningDayOf(момент('2028-03-01T02:00:00'), чч(4))).toBe('2028-02-29');
  });
});

describe('learningDayOf — испорченный переходный час не ломает день', () => {
  // ⚠️⚠️ ЭТИ ПРОВЕРКИ СЛАБЫЕ, И ЭТО НАЗВАНО НАМЕРЕННО. Мутационный прогон показал,
  // что снятие проверок диапазона и NaN их НЕ РОНЯЕТ — мутанты эквивалентные:
  // при любом негодном значении арифметика и так сходится к календарной дате
  // (разбор в комментарии к normalizeTransition). Здесь проверяется ровно то, что
  // проверяемо снаружи: день остаётся определённым и не уезжает на сутки.
  // Сам сторож проверяется ниже, своими тестами, на возвращаемом ЧИСЛЕ.
  it('отрицательный и запредельный час не сдвигают день', () => {
    expect(learningDayOf(момент('2026-01-02T12:00:00'), -60)).toBe('2026-01-02');
    expect(learningDayOf(момент('2026-01-02T12:00:00'), MINUTES_IN_DAY + 60)).toBe('2026-01-02');
  });

  it('NaN трактуется как полночь, а не как «день не определён»', () => {
    expect(learningDayOf(момент('2026-01-02T12:00:00'), Number.NaN)).toBe('2026-01-02');
  });
});

describe('normalizeTransition — сторож настройки, проверяется своим читателем', () => {
  // ⚠️ У сторожа обязан быть СОБСТВЕННЫЙ читатель, иначе он не сторож. Настоящие
  // читатели — экран настроек и вычисление `for_date`: им нужно число, а не дата,
  // и вот там подмена 1500 на «01:00» уже видна пользователю.
  it('годное значение не трогается', () => {
    expect(normalizeTransition(0)).toBe(0);
    expect(normalizeTransition(чч(18))).toBe(1080);
    expect(normalizeTransition(MINUTES_IN_DAY - 1)).toBe(1439);
  });

  it('отрицательное приводится к полуночи', () => {
    expect(normalizeTransition(-1)).toBe(0);
    expect(normalizeTransition(-600)).toBe(0);
  });

  it('⚠️ сутки и больше — к полуночи, а НЕ остатком от деления', () => {
    // 1500 % 1440 = 60 дало бы «01:00» — выдуманную настройку, неотличимую от
    // настоящей. Проверка стоит именно на этом числе.
    expect(normalizeTransition(MINUTES_IN_DAY)).toBe(0);
    expect(normalizeTransition(1500)).toBe(0);
  });

  it('NaN и бесконечности — к полуночи', () => {
    expect(normalizeTransition(Number.NaN)).toBe(0);
    expect(normalizeTransition(Number.POSITIVE_INFINITY)).toBe(0);
    expect(normalizeTransition(Number.NEGATIVE_INFINITY)).toBe(0);
  });

  it('дробное усекается, а не округляется', () => {
    expect(normalizeTransition(60.9)).toBe(60);
  });
});

describe('перевод «минуты ↔ ЧЧ:ММ» для поля ввода', () => {
  it('минуты превращаются в часы с ведущими нулями', () => {
    expect(hhmmOfMinutes(0)).toBe('00:00');
    expect(hhmmOfMinutes(чч(4))).toBe('04:00');
    expect(hhmmOfMinutes(чч(18, 30))).toBe('18:30');
    expect(hhmmOfMinutes(MINUTES_IN_DAY - 1)).toBe('23:59');
  });

  it('негодные минуты показываются как полночь, а не как «NaN:NaN»', () => {
    expect(hhmmOfMinutes(Number.NaN)).toBe('00:00');
    expect(hhmmOfMinutes(-1)).toBe('00:00');
    expect(hhmmOfMinutes(MINUTES_IN_DAY)).toBe('00:00');
  });

  it('строка поля разбирается в минуты', () => {
    expect(minutesOfHHMM('00:00')).toBe(0);
    expect(minutesOfHHMM('04:00')).toBe(240);
    expect(minutesOfHHMM('18:30')).toBe(1110);
    expect(minutesOfHHMM('23:59')).toBe(1439);
  });

  it('⚠️ ПУСТОЕ ПОЛЕ — это не полночь, а «значения нет»', () => {
    // Поле времени отдаёт пустую строку, пока человек стирает и набирает заново.
    // Прочитав её как 0, мы бы молча переставили ему час смены дня на полночь
    // прямо посреди ввода — и календарь разъехался бы у него под руками.
    expect(minutesOfHHMM('')).toBeNull();
    expect(minutesOfHHMM('  ')).toBeNull();
  });

  it('мусор и выход за сутки не разбираются', () => {
    expect(minutesOfHHMM('25:00')).toBeNull();
    expect(minutesOfHHMM('12:60')).toBeNull();
    expect(minutesOfHHMM('вечером')).toBeNull();
    expect(minutesOfHHMM('12')).toBeNull();
  });

  it('обратимость: показать и разобрать даёт то же число', () => {
    for (const m of [0, 1, 240, 719, 720, 1110, 1439]) {
      expect(minutesOfHHMM(hhmmOfMinutes(m))).toBe(m);
    }
  });
});

describe('nextLearningDay', () => {
  it('сдвигает на сутки вперёд', () => {
    expect(nextLearningDay('2026-01-01')).toBe('2026-01-02');
  });

  it('переходит через конец месяца и года', () => {
    expect(nextLearningDay('2026-01-31')).toBe('2026-02-01');
    expect(nextLearningDay('2026-12-31')).toBe('2027-01-01');
  });

  it('переходит через 28 февраля високосного года в 29-е', () => {
    expect(nextLearningDay('2028-02-28')).toBe('2028-02-29');
  });
});
